use std::collections::HashMap;

fn two_sum(nums: Vec<i32>, target: i32) -> Option<(usize, usize)> {
    // Map value -> earliest index where it appears
    let mut first_pos: HashMap<i32, usize> = HashMap::new();

    for (j, &x) in nums.iter().enumerate() {
        // Need y such that y + x == target, and the sum must not overflow i32.
        // If target - x overflows, then no valid i32 y can exist for this x.
        if let Some(y) = target.checked_sub(x) {
            if let Some(&i) = first_pos.get(&y) {
                // Since we scan j increasing and store earliest i for each value,
                // the first match is the lexicographically smallest (i, j) with i < j.
                return Some((i, j));
            }
        }

        // Record earliest index only.
        first_pos.entry(x).or_insert(j);
    }

    None
}